<script setup>
import {computed,shallowRef} from 'vue'
import {markets,hotStocks,fmt,path} from '../data'
import Coin from './Coin.vue'
const props=defineProps({all:Boolean})
const category=shallowRef('全部'),query=shallowRef('')
const visible=computed(()=>markets.filter(m=>(category.value==='全部'||m.category===category.value)&&m.name.toLowerCase().includes(query.value.toLowerCase())).slice(0,props.all?100:8))
</script>
<template><section id="markets" class="market-section"><div class="container"><h2 class="section-heading">{{ $tr("真實價格，") }}<em>{{ $tr("即時呈現 ——") }}</em></h2><p class="eyebrow">{{ $tr("即時市場 · 熱門交易對") }}</p><div class="hot-grid"><div v-for="s in hotStocks" :key="s[0]" class="stock-card"><span>{{ $tr(s[0]) }}</span><strong :class="s[3].startsWith('-')?'negative':'positive'">{{ $tr(s[1]) }}</strong><div :class="s[3].startsWith('-')?'negative':'positive'"><span>{{ $tr(s[2]) }}</span><span>{{ $tr(s[3]) }}</span></div></div></div><div class="market-filters"><div class="tabs"><button v-for="c in ['全部','加密貨幣','外匯','股票']" :key="c" :aria-pressed="category===c" :class="{active:category===c}" @click="category=c">{{ $tr(c) }}</button></div><input v-if="all" v-model="query" :placeholder="$tr(&quot;搜尋交易對&quot;)" :aria-label="$tr(&quot;搜尋交易對&quot;)"/></div><div class="market-table"><table><thead><tr><th>{{ $tr("交易對") }}</th><th>{{ $tr("價格") }}</th><th class="market-extra">{{ $tr("24H 漲跌") }}</th><th class="market-extra">{{ $tr("24H 成交") }}</th><th><span class="sr-only">{{ $tr("操作") }}</span></th></tr></thead><tbody><tr v-for="m in visible" :key="m.id"><td><div class="coin-label"><Coin :symbol="m.symbol"/>{{ $tr(m.name) }}</div><small class="mobile-market-details" :class="m.change<0?'negative':'positive'">{{ $tr(m.change>0?'+':'') }}{{ $tr(m.change.toFixed(2)) }}% · {{ $tr(m.volume) }}</small></td><td>{{ $tr(fmt(m.price)) }}</td><td class="market-extra" :class="m.change<0?'negative':'positive'">{{ $tr(m.change>0?'+':'') }}{{ $tr(m.change.toFixed(2)) }}%</td><td class="market-extra muted">{{ $tr(m.volume) }}</td><td><RouterLink :to="path('/trade/futures/'+m.id)" :aria-label="$tr('交易')+' '+m.name">{{ $tr("去交易 →") }}</RouterLink></td></tr></tbody></table><p v-if="!visible.length" class="empty">{{ $tr("沒有符合的交易對") }}</p><RouterLink class="market-more" :to="path('/trade/futures/BTCUSD')">{{ $tr("看全部 108 個市場 →") }}</RouterLink></div></div></section></template>
